function novoTxid(p) { return (p + Date.now() + 'XXXXXXXXXX').replace(/[^a-zA-Z0-9]/g, 'X').slice(0, 30); }
function novoExtRef() { return Array.from({length: 26}, function () { return 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'[Math.floor(Math.random() * 36)]; }).join(''); }
function saveToken(varName, ativo) {
  const t = pm.response.json().token;
  pm.expect(t).to.match(/^bapi_/);
  pm.environment.set(varName, t);
  if (ativo) pm.environment.set('bapi_token', t);
}
function saveIfPresent(varName, field) {
  try { const v = pm.response.json()[field]; if (v) pm.environment.set(varName, String(v)); } catch (e) {}
}
function assertPdfBinario() {
  pm.test('status 200', () => pm.response.to.have.status(200));
  pm.test('content-type pdf', () => pm.expect(pm.response.headers.get('Content-Type')).to.include('pdf'));
  pm.test('magic bytes %PDF', () => pm.expect(pm.response.text().substring(0, 4)).to.eql('%PDF'));
  ['X-Nosso-Numero', 'X-Nosso-Numero-Formatado', 'X-Nosso-Numero-DV', 'X-Codigo-Barras', 'X-Linha-Digitavel']
    .forEach(h => pm.test('header ' + h, () => pm.expect(pm.response.headers.has(h)).to.be.true));
  pm.test('sem content-encoding residual (T2)', () => pm.expect(pm.response.headers.has('Content-Encoding')).to.be.false);
}
function assertCamposNossoNumero() {
  const b = pm.response.json();
  ['nosso_numero', 'nosso_numero_formatado', 'nosso_numero_dv', 'codigo_barras', 'linha_digitavel']
    .forEach(c => pm.test('campo ' + c, () => pm.expect(b).to.have.property(c)));
}

// ---- status esperado, com 424/422 sensivel a CREDENCIAL ---------------------
// Regra por banco:
//   C6     -> exige TODAS (client_id, client_secret, pfx_base64, pfx_password).
//   Sicoob -> client_id + UMA das duas vias:
//               (a) access_token  (sandbox, dispensa OAuth/mTLS)
//               (b) client_secret + pfx_base64 + pfx_password  (OAuth + mTLS)
//             NENHUMA das duas = ERRO GRAVE (nao e aviso: e ma configuracao).
// 424/422-por-credencial com credencial AUSENTE -> AVISO nomeando o que falta.
// Com a credencial PRESENTE                     -> FALHA (erro real do banco).
var CRED_BANCO = {
  INTER: {
    // client_id + client_secret + material de certificado em UMA das duas
    // formas (par PEM ou PKCS12) — o mesmo que o /bancos publica no esquema.
    obrigatorias: ['inter_client_id', 'inter_client_secret'],
    vias: [
      { nome: 'par PEM (.crt + .key)', chaves: ['inter_cert_pem', 'inter_key_pem'] },
      { nome: 'PKCS12', chaves: ['inter_pfx_base64'] }
    ]
  },
  C6: {
    obrigatorias: ['c6_client_id', 'c6_client_secret', 'c6_pfx_base64'],
    vias: []
  },
  SICOOB: {
    obrigatorias: ['sicoob_client_id'],
    vias: [
      { nome: 'access_token (sandbox)', chaves: ['sicoob_access_token'] },
      { nome: 'OAuth+mTLS', chaves: ['sicoob_client_secret', 'sicoob_pfx_base64'] }
    ]
  }
};
function vazia(k) { return !pm.variables.get(k); }
// Diagnostico de um banco: { faltam: [...], grave: bool }
function diagnosticoBanco(banco) {
  var def = CRED_BANCO[banco];
  if (!def) { return { faltam: [], grave: false }; }
  var faltam = def.obrigatorias.filter(vazia);
  if (def.vias.length) {
    var completa = def.vias.filter(function (v) { return v.chaves.every(function (k) { return !vazia(k); }); });
    if (!completa.length) {
      // nenhuma via satisfeita: e ma configuracao, nao so ausencia
      var parcial = def.vias.some(function (v) { return v.chaves.some(function (k) { return !vazia(k); }); });
      def.vias.forEach(function (v) { faltam = faltam.concat(v.chaves.filter(vazia)); });
      return { faltam: faltam, grave: true, parcial: parcial,
               vias: def.vias.map(function (v) { return v.nome; }) };
    }
  }
  return { faltam: faltam, grave: false };
}
function expandeRequisitos(requer) {
  var out = [];
  (requer || []).forEach(function (k) {
    // Qualquer banco do CRED_BANCO, e nao uma lista fixa: com a lista fixa,
    // banco novo (INTER) caia no ramo generico e o aviso dizia 'FALTA: INTER'
    // em vez de nomear as variaveis que faltam.
    if (CRED_BANCO[k]) { out = out.concat(diagnosticoBanco(k).faltam); return; }
    if (k === 'BANCO') {
      out = out.concat(diagnosticoBanco((pm.variables.get('provider') || 'c6').toUpperCase()).faltam);
      return;
    }
    if (vazia(k)) { out.push(k); }
  });
  return out.filter(function (v, i, a) { return a.indexOf(v) === i; });
}
function faltantesDe(requer) { return expandeRequisitos(requer); }
function registraAviso(nomes) {
  var a = JSON.parse(pm.environment.get('avisos_cred') || '[]');
  a.push({ req: pm.info.requestName, faltam: nomes });
  pm.environment.set('avisos_cred', JSON.stringify(a));
}
function statusEsperado(esperados, requer) {
  var code = pm.response.code;
  var faltam = faltantesDe(requer);
  var corpo = '';
  try { corpo = pm.response.text() || ''; } catch (e) { corpo = ''; }
  var porCredencial = (code === 424) || (code === 422 && /ausente|obrigat|credenc/i.test(corpo));
  if (porCredencial && faltam.length) {
    registraAviso(faltam);
    console.log('AVISO ' + code + ' em ' + pm.info.requestName + ' -> FALTA: ' + faltam.join(', '));
    pm.test('AVISO . ' + code + ' por credencial ausente: ' + faltam.join(', '),
      function () { return true; });
    return;
  }
  pm.test('status em [' + esperados.join(', ') + ']', function () {
    pm.expect(esperados, code === 424
      ? 'credencial configurada e AINDA ASSIM rejeitada pelo banco - erro real'
      : 'status inesperado').to.include(code);
  });
}
